import json
import pandas as pd
import numpy as np
from collections import defaultdict

def task_func(input_file="data.json"):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each numeric key, and returns a sorted Pandas DataFrame.

    Args:
        input_file (str): Path to the JSON file.

    Returns:
        pd.DataFrame: A DataFrame indexed by variable names with columns 'mean' and 'median'.
    """
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        # Return an empty DataFrame with the required columns if file is missing or invalid
        return pd.DataFrame(columns=['mean', 'median'])

    # Ensure data is treated as a list of dictionaries
    if not isinstance(data, list):
        data = [data]

    # Dictionary to store lists of numeric values for each key
    values_map = defaultdict(list)

    for entry in data:
        if not isinstance(entry, dict):
            continue
        for key, value in entry.items():
            # Check if the value is numeric (int or float) and not a boolean
            # (In Python, bool is a subclass of int, so we check explicitly)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_map[key].append(value)

    # Calculate statistics for each key that has numeric data
    stats = {}
    for key, values in values_map.items():
        if values:
            stats[key] = {
                'mean': np.mean(values),
                'median': np.median(values)
            }

    # If no numeric data was found, return empty DataFrame with correct columns
    if not stats:
        return pd.DataFrame(columns=['mean', 'median'])

    # Convert results to a DataFrame
    df = pd.DataFrame.from_dict(stats, orient='index')

    # Sort by the index (variable names)
    df = df.sort_index()

    # Ensure columns are in the correct order
    df = df[['mean', 'median']]

    return df

